// Meta's payload (built in META-WA-SEND-MESSAGE) as WAHA's request. Only approved texts and system values (titles) go out.
const s = $input.first().json;
const start = $('Start').first().json;
const p = typeof start.payload === 'string' ? JSON.parse(start.payload) : start.payload;
const chatId = `${p.to}@c.us`;
let path = '/api/sendText';
let kind = 'text';
let choices = null;
let body;
if (p.type === 'text') {
  body = { session: s.session, chatId, text: p.text.body, linkPreview: false };
} else if (p.type === 'interactive') {
  const i = p.interactive;
  const rows = i.type === 'list' ? i.action.sections.flatMap((x) => x.rows) : i.action.buttons.map((b) => b.reply);
  choices = rows.map((r, n) => ({ n: n + 1, id: r.id, title: r.title }));
  kind = i.type === 'list' ? 'list' : 'buttons';
  body = { session: s.session, chatId, text: `${i.body.text}\n\n${choices.map((c) => `${c.n}) ${c.title}`).join('\n')}`, linkPreview: false };
} else if (p.type === 'document') {
  const ext = String(p.document.filename || '').split('.').pop().toLowerCase();
  const types = { pdf: 'application/pdf', doc: 'application/msword', docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png' };
  path = '/api/sendFile';
  kind = 'document';
  body = { session: s.session, chatId, caption: p.document.caption, file: { url: p.document.link, filename: p.document.filename, mimetype: types[ext] || 'application/octet-stream' } };
} else {
  throw new Error(`WAHA-SEND: no WAHA request for a ${p.type} message`);
}
return [{ json: { url: String(s.base_url || '').replace(/\/+$/, '') + path, body, kind, choices, outbound_id: start.r.outbound_id, wa_id: p.to } }];
